<?php
declare(strict_types=1);
require_once __DIR__.'/includes/location-core.php';
require_once __DIR__.'/includes/media-core.php';

$user=app_require_auth();
if(!app_has_permission('locations.manage',$user)){http_response_code(403);exit('You do not have permission to manage locations.');}
$pdo=app_pdo();$organizationId=(int)$user['organization_id'];$error='';$locations=[];$migrationReady=true;
try{$locations=location_list($pdo,$organizationId,true);}catch(Throwable $e){$migrationReady=false;$error='Location management needs the latest database upgrade. Run Upgrade once, then return here.';error_log('Location admin load failed: '.$e->getMessage());}
$mediaReady=$migrationReady&&media_schema_ready($pdo);

if($migrationReady&&$_SERVER['REQUEST_METHOD']==='POST'){
    try{
        if(!app_verify_csrf($_POST['csrf_token']??null))throw new RuntimeException('Your session token expired. Reload the page and try again.');
        $action=(string)($_POST['action']??'save');$id=max(0,(int)($_POST['id']??0));
        if($action==='save'){
            $payload=[
                'id'=>$id,'name'=>$_POST['name']??'','public_slug'=>$_POST['public_slug']??'','address_line_1'=>$_POST['address_line_1']??'','address_line_2'=>$_POST['address_line_2']??'',
                'city'=>$_POST['city']??'','state'=>$_POST['state']??'','postal_code'=>$_POST['postal_code']??'','country_code'=>$_POST['country_code']??'US','phone'=>$_POST['phone']??'','email'=>$_POST['email']??'',
                'timezone'=>$_POST['timezone']??'','status'=>$_POST['status']??'active','sort_order'=>$_POST['sort_order']??0,'is_primary'=>isset($_POST['is_primary']),
                'dine_in_enabled'=>isset($_POST['dine_in_enabled']),'pickup_enabled'=>isset($_POST['pickup_enabled']),'delivery_enabled'=>isset($_POST['delivery_enabled']),'online_ordering_enabled'=>isset($_POST['online_ordering_enabled']),
                'delivery_radius_miles'=>$_POST['delivery_radius_miles']??'','delivery_minimum'=>$_POST['delivery_minimum']??'','delivery_fee'=>$_POST['delivery_fee']??'','pickup_lead_minutes'=>$_POST['pickup_lead_minutes']??20,
                'delivery_lead_minutes'=>$_POST['delivery_lead_minutes']??45,'latitude'=>$_POST['latitude']??'','longitude'=>$_POST['longitude']??'',
            ];
            if(isset($_POST['manage_hours'])){$hours=[];foreach(location_day_names() as $day=>$_name)$hours[$day]=['is_closed'=>isset($_POST['hours'][$day]['is_closed']),'opens_at'=>$_POST['hours'][$day]['opens_at']??'','closes_at'=>$_POST['hours'][$day]['closes_at']??''];$payload['hours']=$hours;}
            $saved=location_save($pdo,$organizationId,(int)$user['id'],$payload);app_redirect('locations-admin.php?saved=1&edit='.(int)$saved['id']);
        }
        if($id<1)throw new RuntimeException('Choose a location first.');
        if($action==='archive')location_archive($pdo,$organizationId,$id,(int)$user['id']);
        elseif($action==='restore')location_restore($pdo,$organizationId,$id,(int)$user['id']);
        elseif($action==='primary')location_set_primary($pdo,$organizationId,$id,(int)$user['id']);
        else throw new RuntimeException('Unknown location action.');
        app_redirect('locations-admin.php?saved=1');
    }catch(Throwable $e){$error=$e->getMessage();try{$locations=location_list($pdo,$organizationId,true);}catch(Throwable){}}
}

$editId=max(0,(int)($_GET['edit']??$_POST['id']??0));$editing=$editId>0&&$migrationReady?location_get($pdo,$organizationId,$editId):null;
$defaults=['id'=>0,'name'=>'','public_slug'=>'','address_line_1'=>'','address_line_2'=>'','city'=>'','state'=>'','postal_code'=>'','country_code'=>'US','phone'=>'','email'=>'','timezone'=>'America/Phoenix','status'=>'active','is_primary'=>!array_filter($locations,fn($l)=>$l['status']==='active'),'sort_order'=>0,'dine_in_enabled'=>true,'pickup_enabled'=>true,'delivery_enabled'=>false,'online_ordering_enabled'=>false,'delivery_radius_miles'=>'','delivery_minimum'=>'','delivery_fee'=>'','pickup_lead_minutes'=>20,'delivery_lead_minutes'=>45,'latitude'=>'','longitude'=>'','hours'=>[],'hoursText'=>''];
$form=array_merge($defaults,$editing?:[]);
if($_SERVER['REQUEST_METHOD']==='POST'&&($_POST['action']??'')==='save'&&$error!==''){
    foreach(['name','public_slug','address_line_1','address_line_2','city','state','postal_code','country_code','phone','email','timezone','status','sort_order','delivery_radius_miles','delivery_minimum','delivery_fee','pickup_lead_minutes','delivery_lead_minutes','latitude','longitude'] as $key)if(array_key_exists($key,$_POST))$form[$key]=$_POST[$key];
    foreach(['is_primary','dine_in_enabled','pickup_enabled','delivery_enabled','online_ordering_enabled'] as $key)$form[$key]=isset($_POST[$key]);
}
$hoursByDay=[];foreach(($form['hours']??[]) as $hour)$hoursByDay[(int)$hour['day_of_week']]=$hour;$manageHours=!empty($hoursByDay)||isset($_POST['manage_hours']);$savedNotice=($_GET['saved']??'')==='1';
$coverMap=$mediaReady?media_location_cover_map($pdo,$organizationId):[];$coverUrl=$editId>0?($coverMap[$editId]??''):'';
function la_checked(bool $value):string{return $value?' checked':'';}function la_value(mixed $value):string{return app_escape((string)$value);}function la_address(array $l):string{return trim(implode(', ',array_filter([(string)($l['address_line_1']??''),trim((string)($l['city']??'').' '.(string)($l['state']??'').' '.(string)($l['postal_code']??''))])));}
?>
