<section class="card"><div class="eyebrow"><?=$editing?'Edit Location':'New Location'?></div><h2 style="margin-top:5px"><?=$editing?app_escape((string)$editing['name']):'Add restaurant location'?></h2>
<div class="location-cover-editor" id="locationCoverEditor" data-location-id="<?=(int)$form['id']?>" data-csrf="<?=app_escape(app_csrf_token())?>" data-manage="1"><div class="location-cover-row"><div class="cm-preview" data-cover-preview><?=$coverUrl!==''?'<img src="'.app_escape($coverUrl).'" alt="Location cover">':'No cover'?></div><div class="cm-copy"><strong>Location cover image</strong><span>Unique to this store. The menu stays shared; this image identifies the selected location.</span><div class="cm-status" data-cover-status><?=$form['id']>0?($coverUrl!==''?'Cover image active':'JPEG, PNG or WebP · max 10 MB'):'Save this location first, then add its cover image.'?></div></div><div class="cm-actions"><button class="cm-btn primary" type="button" data-cover-upload <?=(!$mediaReady||$form['id']<1)?'disabled':''?>><?=$coverUrl!==''?'Replace':'Upload cover'?></button><button class="cm-btn danger" type="button" data-cover-remove <?=$coverUrl===''?'hidden':''?>>Remove</button></div></div></div>
