<div class="panel-section"><div class="section-label">Ordering operations</div><div class="fields"><div class="field"><label>Pickup lead minutes</label><input name="pickup_lead_minutes" type="number" min="0" max="1440" value="<?=la_value($form['pickup_lead_minutes'])?>"></div><div class="field"><label>Delivery lead minutes</label><input name="delivery_lead_minutes" type="number" min="0" max="1440" value="<?=la_value($form['delivery_lead_minutes'])?>"></div><div class="field"><label>Delivery radius miles</label><input name="delivery_radius_miles" type="number" min="0" max="200" step="0.01" value="<?=la_value($form['delivery_radius_miles'])?>"></div><div class="field"><label>Delivery minimum</label><input name="delivery_minimum" type="number" min="0" step="0.01" value="<?=la_value($form['delivery_minimum'])?>"></div><div class="field"><label>Delivery fee</label><input name="delivery_fee" type="number" min="0" step="0.01" value="<?=la_value($form['delivery_fee'])?>"></div></div></div>
